INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Netzwerksegmentierung eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Netzwerksegmentierung?', 3, '[{"text": "Isolierung von Netzwerkbereichen", "correct": true, "because": "Begrenzt Angriffe"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Physische Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerksegmentierung reduziert Angriffsflächen. b) Sie ist nur für kleine Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch große Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gehören zur Netzwerksegmentierung?', 4, '[{"text": "VLANs", "correct": true, "because": "Virtuelle Netze"}, {"text": "Unklare Methoden", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Subnetze", "correct": true, "because": "IP-Bereiche"}, {"text": "Firewalls", "correct": true, "because": "Trennt Segmente"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne Segmentierung sicher sein?', 2, '[{"text": "Ja", "correct": true, "because": "Aber riskanter"}, {"text": "Nein", "correct ilegal": false, "because": "Segmentierung ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Netzwerksegmentierung im Datenschutz?', 3, '[{"text": "Schützt sensible Daten durch Isolation", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Netzwerksegmentierung nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netze"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein VLAN bei der Netzwerksegmentierung?', 3, '[{"text": "Virtuelle Trennung von Netzwerken", "correct": true, "because": "Isoliert Bereiche"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerksegmentierung erhöht Sicherheit. b) Sie macht Firewalls überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt Firewalls"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Netzwerksegmentierung?', 3, '[{"text": "Angriffe können sich leichter ausbreiten", "correct": true, "because": "Keine Isolation"}, {"text": "Netzwerk wird schneller", "correct": false, "because": "Unsinn"}, {"text": "Daten sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Netzwerksegmentierung ohne VLANs umgesetzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Subnetze möglich"}, {"text": "Nein", "correct": false, "because": "Alternativen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Netzwerksegmentierung?', 3, '[{"text": "Trennung von Gast- und Firmennetz", "correct": true, "because": "Konkret und real"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Netzwerksegmentierung nur für externe Bedrohungen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Risiken"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Netzwerksegmentierung?', 4, '[{"text": "Isolation", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Unklare Trennung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Regelt Datenfluss"}, {"text": "Sicherheitszonen", "correct": true, "because": "Definiert Bereiche"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Netzwerksegmentierung konfiguriert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Regeln nötig"}, {"text": "Nein", "correct": false, "because": "Ohne Konfiguration nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt eine Firewall bei Netzwerksegmentierung?', 3, '[{"text": "Trennt Segmente durch Filter", "correct": true, "because": "Kontrolliert Verkehr"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Netzwerksegmentierung ohne Hardware betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Softwarelösungen möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gefährdet Netzwerksegmentierung?', 3, '[{"text": "Falsche Konfiguration", "correct": true, "because": "Lässt Lücken"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Gute Passwörter", "correct": false, "because": "Unterstützt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerksegmentierung schützt vor Angriffsausbreitung. b) Sie ersetzt ein IDS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt IDS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Netzwerksegmentierung?', 3, '[{"text": "Erhöhte Netzwerksicherheit", "correct": true, "because": "Begrenzt Risiken"}, {"text": "Maximale Offenheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Kontrolle", "correct": false, "because": "Fördert Schutz"}]');